import { createEffect, createSignal } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { getPlayerColorVariants } from "#core/ui/utilities/utilities-color.js";
import {
	getModifierArgumentByContext,
	getModifierTextByContext,
} from "#core/ui/utilities/utilities-core-textprovider.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { Filigree } from "#core/ui-next/components/filigree.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Header } from "#core/ui-next/components/header.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { HSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";
import { useLocalPlayerId } from "#core/ui-next/utilities/game-core-utilities.js";

import { RaiseDiplomacyEvent } from "#base/ui/diplomacy/diplomacy-events.js";
import { OrnatePopupFrame } from "#base/ui-next/components/ornate-popup.jsx";

import style from "#base/ui-next/screens/diplo-message/diplo-message-popup.scss?url";

const debugDismiss = false;
const agendaPopupLegacyName = "diplo-message-popup";
type AttrMap = Readonly<Record<string, string | null>>;
interface AgendaPopupComponentProps {
	attrs: AttrMap;
}

const AgendaPopupComponent = (props: AgendaPopupComponentProps) => {
	let buttonRef!: HTMLDivElement;
	const localPlayerId = useLocalPlayerId();

	const [notificationId, setNotificationId] = createSignal<ComponentID | undefined>();
	const [fgColor, setFgColor] = createSignal<string>("");
	const [bgColor, setBgColor] = createSignal<string>("");
	const [relationshipChange, setRelationshipChange] = createSignal<number>(0);
	const [leaderId, setLeaderId] = createSignal<number>(-1);
	const [leaderType, setLeaderType] = createSignal<string>("UNKNOWN_LEADER");
	const [leaderName, setLeaderName] = createSignal<string>("UNKNOWN_LEADER");
	const [leaderMessage, setLeaderMessage] = createSignal<string>("LOC_DIPLO_RELATIONSHIP_INCREASED_GENERIC");
	const [portraitContext, setPortraitContext] = createSignal<string>("");
	const [agendaName, setAgendaName] = createSignal<string>("");
	const [agendaDesc, setAgendaDesc] = createSignal<string>("");

	const onClose = () => {
		ContextManager.pop(agendaPopupLegacyName);

		const _notificationID = notificationId();
		if (_notificationID && !debugDismiss) {
			Game.Notifications.dismiss(_notificationID);
		}
	};

	const raiseLeader = () => {
		window.dispatchEvent(new RaiseDiplomacyEvent(leaderId()));
		onClose();
	};

	createEffect(() => {
		const rawNotificationID = props.attrs["data-notification-id"];
		if (rawNotificationID) {
			setNotificationId(JSON.parse(rawNotificationID) as ComponentID);
		}
		setRelationshipChange(Number(props.attrs["data-relationship-change"] ?? "0"));
		const isPositiveChange = relationshipChange() >= 0;
		const fromLeaderId = Number(props.attrs["data-from-player"] ?? "0");

		const fromLeader = Players.get(fromLeaderId);
		if (!fromLeader) {
			console.error("diplo-message-popup: fromPlayer expected but not found!");
			return;
		}

		const playerDiplomacy = fromLeader.Diplomacy;
		if (!playerDiplomacy) {
			console.error("diplo-message-popup: playerDiplomacy not found!");
			return;
		}

		const eModifierId = props.attrs["data-modifier-id"] ?? "";
		if (eModifierId) {
			const name =
				getModifierArgumentByContext(eModifierId, "ModName") || getModifierTextByContext(eModifierId, "Name");
			const description =
				getModifierArgumentByContext(eModifierId, "Tooltip") ||
				getModifierTextByContext(eModifierId, "Tooltip");

			setAgendaName(name);
			setAgendaDesc(description);
		}

		const leaderDef = GameInfo.Leaders.lookup(fromLeader.leaderType);
		if (leaderDef) {
			setLeaderId(fromLeaderId);
			setLeaderType(leaderDef.LeaderType);
			setLeaderName(leaderDef.Name);

			if (isPositiveChange) {
				const key = "LOC_DIPLO_RELATIONSHIP_INCREASED_" + leaderType();
				if (Locale.keyExists(key)) {
					setLeaderMessage(key);
				} else {
					setLeaderMessage("LOC_DIPLO_RELATIONSHIP_INCREASED_GENERIC");
				}
			} else {
				const key = "LOC_DIPLO_RELATIONSHIP_DECREASED_" + leaderType();
				if (Locale.keyExists(key)) {
					setLeaderMessage(key);
				} else {
					setLeaderMessage("LOC_DIPLO_RELATIONSHIP_DECREASED_GENERIC");
				}
			}
		}
		const variants = getPlayerColorVariants(fromLeaderId);
		if (variants) {
			setBgColor(variants.primaryColor.mainColor);
			setFgColor(variants.secondaryColor.mainColor);
		}
		const audio = useAudio("AgendaScreen");

		if (playerDiplomacy) {
			switch (playerDiplomacy.getRelationshipEnum(localPlayerId())) {
				case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_HOSTILE:
				case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_UNFRIENDLY:
					if (isPositiveChange) {
						setPortraitContext("");
						audio("positive-showing");
					} else {
						setPortraitContext("LEADER_ANGRY");
						audio("negative-showing");
					}
					break;
				case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_FRIENDLY:
				case DiplomacyPlayerRelationships.PLAYER_RELATIONSHIP_HELPFUL:
					if (isPositiveChange) {
						setPortraitContext("LEADER_HAPPY");
						audio("positive-showing");
					} else {
						setPortraitContext("");
						audio("negative-showing");
					}
					break;
				default:
					if (isPositiveChange) {
						setPortraitContext("LEADER_HAPPY");
						audio("positive-showing");
					} else {
						setPortraitContext("LEADER_ANGRY");
						audio("negative-showing");
					}
					break;
			}
		}
	});

	return (
		<Panel
			name="Agenda Popup"
			id={agendaPopupLegacyName}
			onCancelInput={() => {
				onClose();
			}}
			class="relative"
		>
			<div class="absolute top-0 bottom-0 left-3 right-3 bg-black" />
			<OrnatePopupFrame
				class="pb-2 relative max-w-192 min-w-96"
				closePopupCallback={() => {
					onClose();
				}}
				noClose={true}
			>
				{/* Radial Glows */}
				<div class={`absolute overflow-hidden h-full w-full self-center opacity-50 top-1`}>
					<div
						class={`absolute h-full w-full self-center`}
						style={{
							"background-image": `radial-gradient(closest-side, ${bgColor()}, transparent)`,
							top: "-40%",
						}}
					/>
					<div
						class={`absolute h-full w-full self-center`}
						style={{
							"background-image": `radial-gradient(closest-side, ${bgColor()}, transparent)`,
							bottom: "-66%",
						}}
					/>
				</div>
				{/* Corner Ornaments */}
				<div
					class="absolute top-1 left-1 rotate-180 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div
					class="absolute top-1 right-1 -rotate-90 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div
					class="absolute bottom-1 left-4 rotate-90 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div
					class="absolute bottom-1 right-4 size-4 bg-contain opacity-30"
					style={{ "background-image": "url(blp:mp_player_detail)" }}
				/>
				<div class={`absolute flex flex-row items-center justify-center`}>
					<div
						class={`absolute bg-center bg-no-repeat bg-contain size-25`}
						style={{
							"background-image": "url(blp:subsystem_panel_header_icon_backing)",
							// solid just isn't recognizing our custom tint filter here
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": fgColor(),
						}}
					/>
					<div class={`absolute leader-frame size-28`} />
					<Icon
						class="absolute size-32 -top-18"
						name={UI.getIconCSS(leaderType(), portraitContext())}
						isUrl={true}
					/>
				</div>
				<Header class={`mt-12 max-w-full text-center justify-center text-shadow-subtle relative`}>
					<div class="flex flex-row">
						<L10n.Stylize
							text={"LOC_DIPLOMACY_AGENDA_TITLE"}
							class="text-sm"
						/>
						<Tooltip.Text
							initialHPosition={TooltipHorizontalPosition.RIGHT}
							initialVPosition={TooltipVerticalPosition.CENTER}
							header={agendaName()}
							text={agendaDesc()}
						>
							<Activatable
								class="size-5 bg-no-repeat bg-cover ml-1 -top-0\.5"
								style={{ "background-image": "url(blp:icon_info)" }}
								tabIndex={-1}
							/>
						</Tooltip.Text>
					</div>
					<L10n.Stylize
						text={Locale.compose(agendaName())}
						class="text-xl"
					/>
				</Header>
				<div class="relative flex flex-col justify-center items-center">
					<Filigree.Small />
					<L10n.Stylize
						text={relationshipChange() >= 0 ? agendaDesc() + "_LIKES" : agendaDesc() + "_DISLIKES"}
						class="text-accent-3"
					/>
					<div class="relationship-delta-bg p-2 m-1 mt-3">
						<L10n.Stylize
							text={"LOC_DIPLOMACY_AGENDA_CHANGE_DESCRIPTION"}
							args={[relationshipChange()]}
							class={relationshipChange() >= 0 ? "text-positive" : "text-negative"}
						/>
					</div>
					<div class="minimal-card-bg flex flex-col flex-auto self-stretch items-center m-4 opacity-100 p-1">
						<div class="relative solid-card-bg p-3 px-9 flex flex-col self-stretch items-center justify-center">
							<div class="relative self-start size-6 -left-6 diplo-message-quote-r" />
							<L10n.Stylize text={leaderMessage()} />
							<div class="relative self-end size-6 -right-6 diplo-message-quote-l" />
						</div>
					</div>
					<HSlot autoFocus={true}>
						<Activatable
							class={`justify-center items-center flex flex-row mb-4 p-4 relative group`}
							hotkeyAction="accept"
							onActivate={raiseLeader}
							suppressPointerChanges={true}
							disabled={!IsControllerActive()}
						>
							<Button
								class="mr-3"
								hotkeyAction="accept"
								onActivate={raiseLeader}
								tabIndex={-1}
								autoFocus={true}
							>
								<NavHelp class="mr-2" />
								<L10n.Compose text={"LOC_DIPLOMACY_VIEW_LEADER"} />
							</Button>
							<Button
								ref={buttonRef}
								hotkeyAction="cancel"
								class=""
								onActivate={onClose}
								tabIndex={-1}
							>
								<NavHelp class="mr-2" />
								<L10n.Compose text={"LOC_NOTIFICATION_DISMISS"} />
							</Button>
						</Activatable>
					</HSlot>
				</div>
			</OrnatePopupFrame>
		</Panel>
	);
};

export const AgendaPopup = ComponentRegistry.register({
	name: "Agenda",
	createInstance: AgendaPopupComponent,
});

ComponentUtilities.loadStyles(style);

defineLegacyComponent(
	agendaPopupLegacyName,
	{
		attrs: {
			"data-notification-id": "-1",
			"data-notification-type": "-1",
			"data-from-player": "-1",
			"data-to-player": "-1",
			"data-relationship-change": "-1",
			"data-modifier-id": "-1",
		},
	},
	(attrs) => {
		Input.setActiveContext(InputContext.Shell);
		return <AgendaPopupComponent attrs={attrs} />;
	},
);
